"""Write SECTIONS for 2026-09-24 into feishu_write_doc.py (regex replace)."""
import re

SECTIONS = [{'title': '一、海洋人工智能', 'en': 'Ocean AI / Marine Artificial Intelligence', 'items': [{'title': '滑动EOF耦合深度学习：风浪场时空预报新框架', 'badge': '[论文]', 'abstract': '针对海上作业与海岸防灾对风浪场预报的需求，Ocean Engineering 刊文提出将滑动经验正交函数（EOF）分解与深度学习耦合的时空预报框架。滑动EOF仅在历史滚动窗口内做分解，避免未来信息泄漏，使EOF表示能响应局地演变的风浪变率，再由时序预报网络输出风浪场，为大范围风浪预报提供了抑制信息泄漏的处理范式。', 'source': 'Ocean Engineering', 'url': 'https://doi.org/10.1016/j.oceaneng.2026.128219', 'date': '2026-09-22'}, {'title': '图神经网络改进南极海冰密集度周尺度预报', 'badge': '[论文]', 'abstract': 'Scientific Reports 刊文指出，南极海冰近年出现突变且机理不清，数周尺度预报需求迫切；常规卷积网络在规则欧氏网格上运行，难以显式表达长程空间依赖与不规则的区域相互作用。研究以图神经网络刻画海冰强烈非线性、非均质且快速演变的动力特征，改进周尺度密集度预报，为统计与动力方法之外的第三条技术路线。', 'source': 'Scientific Reports', 'url': 'https://doi.org/10.1038/s41598-026-70984-7', 'date': '2026-09-16'}, {'title': 'ECHO：用稀疏新观测修正已发布的海冰预报', 'badge': '[论文]', 'abstract': 'arXiv 2609.24591 研究发现，海冰预报发布后误差累积的位置具有结构性：固定传播方式的误差集中在高梯度冰缘，而均质内区几乎不需要传播，说明修正的传播距离应随状态变化。作者提出 ECHO（证据引导的异质传播修正），其中 ECHO-Scale 自适应调整传播距离、ECHO-Delta 学习固定传播附近的有界残差；在覆盖不同先验、观测时刻、稀疏度、几何与噪声条件的 96 组标准评估设置下均优于固定传播，代码已开源。', 'source': 'arXiv (cs.LG)', 'url': 'https://arxiv.org/abs/2609.24591', 'date': '2026-09-21'}, {'title': '分布感知深度学习订正有效波高模拟偏差（西北太平洋）', 'badge': '[论文]', 'abstract': 'JGR: Machine Learning and Computation 刊文指出，数值波浪模式输出常因风强迫、物理参数化与水深的不确定性而存在系统性偏差。研究在西北太平洋对有效波高开展深度学习偏差订正，融合多源环境预测因子并采用分布感知损失函数，预测模型采用U-Net时空架构并优于对照方案，为海浪后报数据集构建提供订正工具。', 'source': 'JGR: Machine Learning and Computation', 'url': 'https://doi.org/10.1029/2026jh001338', 'date': '2026-09-17'}, {'title': '深度强化学习实现多AUV编队控制：分解运动学与动力学两层', 'badge': '[论文]', 'abstract': 'Engineering Applications of Artificial Intelligence 刊文针对多台相似自主水下航行器（AUV）编队控制中“仿真到现实”动态差距（水动力参数与未知扰动）这一主要障碍，将问题分解为运动学层的期望目标点生成与动力学层的跟踪控制，配合深度强化学习求解，并面向动态编队间距场景验证，为多AUV协同作业提供可迁移的控制范式。', 'source': 'Engineering Applications of AI', 'url': 'https://doi.org/10.1016/j.engappai.2026.116239', 'date': '2026-09-22'}]}, {'title': '二、海洋数字孪生', 'en': 'Ocean Digital Twin', 'items': [{'title': '相干结构的数据同化：理想化海洋涡旋研究', 'badge': '[论文]', 'abstract': 'Nonlinear Processes in Geophysics 刊文指出，海洋涡旋等相干结构可由位置、振幅、形状等少量属性刻画；当线性高斯数据同化直接作用于网格场、缺少结构层面的先验调整时，背景与观测的线性叠加会扭曲这些属性，尤其在位移不确定占主导的情形下。研究以理想化涡旋为试验场，讨论参数化空间与网格空间两种同化路径，为涡分辨资料的业务同化提供方法学参考。', 'source': 'Nonlinear Processes in Geophysics', 'url': 'https://doi.org/10.5194/npg-33-489-2026', 'date': '2026-09-21'}, {'title': '数字孪生渔场框架：耦合水下视觉感知与多变量水质预报', 'badge': '[论文]', 'abstract': 'Aquacultural Engineering 刊文构建数字孪生渔场，把水下视觉感知与多变量水质预报耦合到统一时空基准。改进YOLOv8（引入可变形卷积与坐标注意力）实现高浊度水体的鱼群检测、摄食活动分析与异常目标定位，mAP@0.5 达 90.4%；Transformer 多变量时序模型结合分位数回归，对溶解氧、温度、pH、浊度、盐度与氨氮给出分级预警与预测区间。14天连续监测试验（196小时视频、1344条水质记录）显示物理与虚拟状态同步误差不超过 9.7 毫秒与 3.2 像素，模拟缺氧与氨氮事件的平均预警提前 28.7 分钟。', 'source': 'Aquacultural Engineering', 'url': 'https://doi.org/10.1016/j.aquaeng.2026.102822', 'date': '2026-09-16'}, {'title': '全球有效波高融合格网数据集：高度计＋数值后报', 'badge': '[数据]', 'abstract': 'Earth System Science Data 刊文指出，卫星高度计虽能提供长期高精度有效波高观测，但时空采样稀疏导致波候分析出现欠采样误差。研究以 WAVEWATCH III 后报作为背景场，对多任务高度计数据做离线融合，构建全球有效波高格网数据集，可作为波浪模式评估、再分析与数字孪生底座的基础数据产品。', 'source': 'Earth System Science Data', 'url': 'https://doi.org/10.5194/essd-18-6841-2026', 'date': '2026-09-16'}, {'title': '海洋“记住”短暂大气振荡：季节内强迫转换为ENSO可预报性的新指标', 'badge': '[论文]', 'abstract': '中科院海洋研究所团队在 npj Climate and Atmospheric Science 发文，揭示西太平洋上层海流 20—90 天季节内变化如何被累积成持续数月的东向环流异常：只有起源于印度洋、东传至西太平洋并产生持续强西风的大气季节内振荡（MJO）事件，才能在海洋留下显著印记；多次同向强迫经海洋调整逐步累积，增强纬向热输送并把热量推往中东太平洋。该海流短期波动可提前约 8 个月预示厄尔尼诺核心区水温变化，纳入传统模型后显著提升预测能力，为ENSO早期诊断补充了动力指标。', 'source': '中科院海洋研究所 / npj Climate and Atmospheric Science', 'url': 'https://doi.org/10.1038/s41612-026-01531-4', 'date': '2026-09-16'}, {'title': '印度洋波动加剧美国东岸高潮位洪涝：跨洋气候联动机制', 'badge': '[论文]', 'abstract': '中科院海洋研究所团队在 Communications Earth & Environment 发文，基于过去 70 余年大西洋沿岸潮位站资料发现：1990 年以来的洪水加剧由全球变暖海平面上升驱动，而 2000 年以后的加速主要由海平面 10—20 年中短期变化引起，并非潮差或台风风暴潮增加。数值试验显示，2000 年后海面热交换改变海水密度、减缓大西洋内部翻转流；研究首次证实源头是半个地球之外的印度洋偶极子，通过高空大气波动改变北大西洋环流与海表热分布，为沿海洪水预测提供新因子。', 'source': '中科院海洋研究所 / Communications Earth & Environment', 'url': 'https://doi.org/10.1038/s43247-026-03932-y', 'date': '2026-09-23'}]}, {'title': '三、海洋可视化', 'en': 'Ocean Visualization', 'items': [{'title': 'Copernicus Marine 发布 MyOcean Pro 可视化器 v17：新增三维地球视图', 'badge': '[工具]', 'abstract': 'Copernicus Marine 于 9 月 23 日发布 MyOcean Pro Viewer v17，新增三维地球投影（新一代三维可视化引擎的概念验证，可替代原有二维投影）、跨应用的统一登录（SSO）、个人目录内直接拖拽上传用户数据并转换为 ARCO 格式、时间/深度值手动输入，以及多图时间轴与深度轴对齐——便于把原位观测与 MyOcean 数据集放在同一坐标下对比，明显提升了海洋数据探索与比对效率。', 'source': 'Copernicus Marine (CMEMS)', 'url': 'https://help.marine.copernicus.eu/en/articles/16844213-new-features-of-myocean-pro-viewer-v17', 'date': '2026-09-23'}, {'title': '南海内孤立波中潜体沉浸式人机交互仿真与应急浮力控制', 'badge': '[论文]', 'abstract': 'Ocean Engineering 刊文用 MITgcm 模拟南海高分辨率内孤立波数据，基于等密度面深度提取实现内孤立波的连续三维可视化；结合多自由度动力学模型研究潜体在内孤立波中的运动响应，并设计应急浮力控制策略，把海洋动力过程可视化、潜体运动仿真与安全控制串成一条链路。', 'source': 'Ocean Engineering', 'url': 'https://doi.org/10.1016/j.oceaneng.2026.128029', 'date': '2026-09-15'}, {'title': 'GIS-AHP 评估东非海岸带热带气旋脆弱性（达累斯萨拉姆）', 'badge': '[论文]', 'abstract': 'Geomatics, Natural Hazards and Risk 刊文采用 IPCC 评估框架，以暴露度、敏感性与适应能力三类共 17 项指标评估达累斯萨拉姆海岸带的脆弱性空间格局。指标权重由基于 GIS 的层次分析法（AHP）成对比较确定，并结合文献与三方共识讨论校准，输出可用于规划决策的脆弱性制图结果。', 'source': 'Geomatics, Natural Hazards and Risk', 'url': 'https://doi.org/10.1080/19475705.2026.2731736', 'date': '2026-09-15'}, {'title': '多波束测深绘制大加那利岛海底地貌图（1:100万）', 'badge': '[数据]', 'abstract': 'Journal of Maps 刊文基于 2024 年两次科考的 Hydrosweep DS 多波束测深数据，覆盖大加那利岛周边约 2.1 万平方公里、水深 54 至 3650 米，绘制 1:100 万比例尺海底地貌图并归纳地貌单元与成因过程，是可复用的公开海底地形图件产品。', 'source': 'Journal of Maps', 'url': 'https://doi.org/10.1080/17445647.2026.2735222', 'date': '2026-09-22'}, {'title': 'LeadNet 与 80 米分辨率泛北极冬季冰间水道数据集', 'badge': '[论文]', 'abstract': '中科院海洋所人工智能海洋学研究组提出面向 Sentinel-1 SAR 影像的冰间水道智能检测模型 LeadNet，并据此构建 80 米分辨率的泛北极冬季冰间水道数据集。LeadNet 为双分支结构，分别从 Sentinel-1 HH 极化后向散射影像与灰度共生矩阵纹理中提取特征并在编码阶段融合，以增强复杂海冰背景下细窄水道的识别能力；测试覆盖格陵兰海、楚科奇海、波弗特海、喀拉海、东西伯利亚海及北极中央区，平均交并比 mIoU 0.78、Kappa 0.73，对 100—300 米宽的细窄水道仍保持较好识别能力。研究处理了 2019 年 10 月至 2020 年 4 月北纬 65°以北的 14093 景 Sentinel-1 超宽幅影像，生成含逐景分类结果与逐月频率图的数据集（GeoTIFF，约 1.09 TB，已公开）；形态统计显示宽度小于 300 米或长度小于 5 公里的水道贡献了总水道面积的约 20%—40%，在晚冬与早春显著增加。', 'source': 'International Journal of Digital Earth / 中科院海洋所', 'url': 'https://doi.org/10.1080/17538947.2026.2728309', 'date': '2026-09-10'}]}, {'title': '四、海洋数据质量', 'en': 'Ocean Data Quality', 'items': [{'title': '挑战者深渊全海深测深：深度估计的不确定性来自哪里', 'badge': '[论文]', 'abstract': 'Scientific Data 刊文公开 2023 年“白凤丸”KH-23-9 航次用 Kongsberg EM124 多波束采集的挑战者深渊全海深测深数据集：沿东西与南北向测线、航速 4—15 节施测，基于同期 XCTD 与历史全深度 CTD 构建 5 组海水声速模型并开展深度估计敏感性试验。结果显示测深保留率随航速升高而下降（4 节约 87%、15 节约 78%），南北向测线在穿越地形陡变处波动更大，精确的全海深制图不仅取决于测深仪，还取决于航速、测线取向、船体运动、声速与波束足印；原始与处理后数据、格网、声速模型及船载配置均公开，便于后续再分析。', 'source': 'Scientific Data（经 phys.org 报道）', 'url': 'https://doi.org/10.1038/s41597-026-08267-z', 'date': '2026-09-16'}, {'title': '超强厄尔尼诺破纪录：Niño3.4 海温异常达 3.05℃', 'badge': '[要闻]', 'abstract': '据 NOAA 海表温度数据，以 1991—2020 年为基准，赤道中太平洋 Niño3.4 区海温异常已达 3.05℃，超过 2015 年 11 月创下的 3.02℃ 纪录，且比历史峰值期提前约两个月；采用海洋尼诺指数（ONI）口径，9 月 19 日日异常达 3.07℃，与此前 3.08℃ 的纪录在统计意义上持平。综合 14 个季节预测模型的测算，本次事件峰值或升至约 4.1℃，WMO 与 NOAA 均提示其影响将持续至 2027 年初——对海洋观测与季节预报体系是一次极端检验。', 'source': '澎湃新闻（NOAA 数据）', 'url': 'https://www.toutiao.com/article/7688344831797592619/', 'date': '2026-09-22'}, {'title': '重力-地质法反演水深的异方差不确定性量化', 'badge': '[论文]', 'abstract': 'Computational Geosciences 刊文指出，重力-地质法（GGM）被广泛用于由卫星重力异常反演水深，但一直缺乏稳健的不确定性量化框架；传统方法假设同方差高斯误差，在复杂地形下并不成立。研究改假设预测残差服从零均值拉普拉斯分布，发现其尺度参数同时依赖预测水深与地形粗糙度并加以参数化，从而给出随地形变化的水深误差场。', 'source': 'Computational Geosciences', 'url': 'https://doi.org/10.1007/s10596-026-10498-3', 'date': '2026-09-17'}, {'title': 'CYGNSS 星间与通道间一致性检验：CNN 风速反演的可靠性边界', 'badge': '[论文]', 'abstract': 'Remote Sensing Letters 刊文评估基于卷积神经网络的 CYGNSS GNSS-R 海面风速反演在不同卫星、以及同一卫星不同延迟-多普勒图（DDM）通道之间是否存在可测量的性能差异。研究用 2022 年匹配的 CYGNSS 与 ERA5 数据分别训练 7 颗卫星的独立模型与多星联合模型，并在 2023 年 1、4、7、10 月的观测上测试，为多星融合产品的质量控制与偏差溯源提供依据。', 'source': 'Remote Sensing Letters', 'url': 'https://doi.org/10.1080/2150704x.2026.2731605', 'date': '2026-09-20'}]}, {'title': '五、海洋数据处理', 'en': 'Ocean Data Processing', 'items': [{'title': 'OcDiffSR：条件扩散模型实现亚得里亚海海洋场超分辨率', 'badge': '[论文]', 'abstract': 'arXiv 2609.22574 提出 OcDiffSR——面向海洋场超分辨率的条件去噪扩散概率模型，从粗分辨率再分析输入重建高分辨率海表场。模型在 2011—2020 年配对的低分辨率（GLORYS12V1，1/12°）与高分辨率（地中海物理再分析 Med MFC，1/24°）数据上训练，在 2009 年亚得里亚海独立测试年评估；条件U-Net引入多尺度低分辨率编码器、交叉注意力瓶颈与基于 FiLM 的季节嵌入，联合超分海表温度、盐度与水平流速。相较双线性插值与残差扩散模型 CorrDiff，标量场误差显著降低（RMSE：SST 0.477℃、SSS 0.346 psu），相关系数不低于 0.999、结构相似度不低于 0.964。', 'source': 'arXiv (physics.ao-ph)', 'url': 'https://arxiv.org/abs/2609.22574', 'date': '2026-09-18'}, {'title': '弥合原位数据缺口：面向新兴经济体的卫星-模式业务化监测框架', 'badge': '[论文]', 'abstract': 'Frontiers in Marine Science 刊文指出，新兴与发展中经济体往往缺乏维持原位海洋观测网的财力、技术与制度能力，从而放大了有害藻华与海洋热浪等灾害的暴露与敏感性。文章给出一套以用户需求为起点、由本地科研力量共建的业务化海洋监测框架，说明在缺少现场观测的条件下如何以卫星数据与数值模式组合支撑决策。', 'source': 'Frontiers in Marine Science', 'url': 'https://doi.org/10.3389/fmars.2026.1934010', 'date': '2026-09-22'}, {'title': '智能手机分析平台：海水营养盐、重金属与新污染物便携监测综述', 'badge': '[论文]', 'abstract': 'Critical Reviews in Analytical Chemistry 发表综述指出，常规海水分析手段仍以实验室为主、成本高且难以实时现场监测；智能手机分析平台因便携、低成本、易用而快速兴起。文章系统梳理了基于智能手机的海水营养盐、重金属与新兴污染物检测方案，为把“现场快检数据”接入海洋数据处理链条提供技术选型参考。', 'source': 'Critical Reviews in Analytical Chemistry', 'url': 'https://doi.org/10.1080/10408347.2026.2729456', 'date': '2026-09-13'}, {'title': '考虑海浪状态的风应力新参数化方案提升风暴潮与海浪模拟', 'badge': '[论文]', 'abstract': '中科院海洋所灾害性海洋动力过程研究组针对近海强风下海气动力参数化不确定性大的问题，提出考虑海浪状态的风应力参数化方案。研究基于多个海区观测资料，发现近岸强风条件下主导波浪的波陡能较好表征风应力变化，据此构建同时考虑观测高度、主导波长与波陡的参数化形式。将该方案应用于台风“梅花”影响下东海近岸风暴潮—海浪耦合模拟，结果表明传统仅依赖 10 米风速的经验公式在强风浪下明显低估风应力及其驱动的海洋动力响应，而新方案使风暴潮与有效波高模拟更接近观测，有效降低了近海极端动力过程模拟的不确定性。成果发表于 Journal of Physical Oceanography。', 'source': 'Journal of Physical Oceanography / 中科院海洋所', 'url': 'https://qdio.cas.cn/2019Ver/News/kyjz/202609/t20260911_8280846.html', 'date': '2026-09-11'}, {'title': '语义子原型网络：遥感影像海洋溢油检测', 'badge': '[论文]', 'abstract': '遥感监测海洋溢油对海洋环境保护、污染监管与应急处置至关重要，但油水边界模糊不规则、油膜常常小且破碎、溢油外观随油膜厚度与光照变化，导致精准检测困难。Marine Pollution Bulletin 在线论文提出基于语义子原型的检测方法，通过构建具判别性的类别子原型表征来应对类内差异大、样本不均衡的问题，提升复杂海况下溢油区域的识别能力，为遥感溢油业务化监测提供方法支撑。', 'source': 'Marine Pollution Bulletin', 'url': 'https://doi.org/10.1016/j.marpolbul.2026.120317', 'date': '2026-09-18'}]}, {'title': '六、数据管理与共享', 'en': 'Data Management & Sharing', 'items': [{'title': 'OceanEye 国际联盟启动：为 GOOS 募集逾 2.11 亿欧元承诺', 'badge': '[要闻]', 'abstract': '9 月 23 日，欧盟委员会主席 von der Leyen 与加拿大总理 Carney 在纽约第 81 届联大高级别周期间共同主持高级别认捐活动，正式启动 OceanEye 国际联盟，为全球海洋观测系统（GOOS）募集约 2.11 亿欧元（超 3.39 亿美元）资金与实物承诺，联盟成员已增至 31 个；欧盟追加投入用于观测网络、新技术研发与维持原位海洋数据的国际流动，加拿大承诺五年内投入 8200 万加元。GOOS 由 IOC-UNESCO 与 WMO 共同主办，依托 64 国 8000 个平台每日提供约 12 万次原位观测，资金承诺将用于维持现有观测平台、填补关键数据缺口并强化 OceanOPS 数据报告中心。', 'source': 'EuroGOOS / 欧盟委员会', 'url': 'https://eurogoos.eu/news/oceaneye-international-alliance-mobilises-new-commitments-to-strengthen-the-global-ocean-observing-system', 'date': '2026-09-23'}, {'title': 'ABLOS 第33次会议举办“海洋数据共享与海洋法”研讨会', 'badge': '[要闻]', 'abstract': '9 月 14—17 日，国际水文组织（IHO）、国际大地测量协会（IAG）与海洋法咨询委员会（ABLOS）第 33 次会议在葡萄牙水文研究所举行，其中 9 月 16 日举办“海洋数据共享与海洋法”研讨会，与 IOC-UNESCO 合作。会议贯穿“尽可能开放、必要时受限”的原则，议题涵盖海底与大陆架知识缺口、BBNJ 协定、海洋空间规划、智能海底电缆的地震与海底监测潜力，以及“可访问”正在扩展为“可被机器使用”的数据可用性要求。', 'source': '葡萄牙水文研究所（IH）', 'url': 'https://www.hidrografico.pt/en/news/noticias-do-antigo-site/instituto-hidrografico-recebe-o-seminario-oceanic-data-sharing-and-the-law-of-the-sea', 'date': '2026-09-16'}, {'title': '海洋 eDNA 的成本-灵敏度权衡：标准化流程下的过滤与重复策略', 'badge': '[论文]', 'abstract': 'PLOS ONE 刊文在加州 Point Conception 潮间带，用统一实验室流程比较不同滤膜类型与下游处理的过滤方案、野外与实验室重复、以及独立与合并 PCR 重复对 eDNA 物种丰富度累积的影响。结果显示成本高效的过滤与重复策略可匹配甚至超过更高投入方案的检测灵敏度（使用 12S 核糖体标记），为高通量海洋 eDNA 监测的资源配置提供实证依据。', 'source': 'PLOS ONE', 'url': 'https://doi.org/10.1371/journal.pone.0350111', 'date': '2026-09-10'}, {'title': '公海深海底层渔业生态系统管理标准：南太平洋实践', 'badge': '[论文]', 'abstract': 'Journal of Northwest Atlantic Fishery Science 刊文介绍南太平洋区域渔业管理组织（SPRFMO）依据公约要求落实生态系统方法的经验：以底层渔业影响评估标准与遭遇审查标准为指引，规范对底层捕捞（含新渔业与探捕渔业）在脆弱海洋生态系统上的累积影响评估，为公海深海渔业的数据与评估标准化提供可借鉴范例。', 'source': 'Journal of Northwest Atlantic Fishery Science', 'url': 'https://doi.org/10.2960/j.v57.m760', 'date': '2026-09-11'}, {'title': 'CF 公约社区研讨会 2026：推进环境数据标准与互操作', 'badge': '[动态]', 'abstract': 'CF（Climate and Forecast）公约社区研讨会 2026 于 9 月 21—24 日在德国波恩 ECMWF 以线上线下混合方式举行，由 Copernicus 气候变化服务等支持。会议汇聚全球 CF 社区的研究者、开发者与数据专家，围绕气候与预报元数据标准的最新进展开展全体会议、特邀报告与互动讨论，并设置实操黑客松与分组专题，旨在推进环境数据的标准、协作与互操作性。CF 公约是海洋与大气数据共享中应用最广的自描述元数据规范之一，其演进直接影响海洋观测与模式数据的可发现性与可互操作程度。', 'source': 'Copernicus Climate Change Service (C3S)', 'url': 'https://climate.copernicus.eu/cf-conventions-community-workshop-2026', 'date': '2026-09-21'}]}, {'title': '七、开放航次与科考', 'en': 'Open Cruises & Expeditions', 'items': [{'title': '原住民知识与现场观测提升北冰洋模式能力与相关性', 'badge': '[论文]', 'abstract': 'Communications Earth & Environment 刊文指出，海洋模式日益成为理解与预判海洋生态系统变化的核心工具，但其开发几乎完全排除了长期观测、依赖并守护这些环境的原住民群体。研究提出通过与原住民观测者建立持续双向伙伴关系来构建北冰洋模式的框架，以阿拉斯加北极观测与知识中心（AAOKH）为合作对象，用季节历把 Iñupiat 观测者的口述观测与模式输出对应起来，提升了模式对当地实际关切的能力与相关性。', 'source': 'Communications Earth & Environment', 'url': 'https://doi.org/10.1038/s43247-026-03899-w', 'date': '2026-09-18'}, {'title': 'OCEANS 2026 Monterey 会议举行（9月21—24日）', 'badge': '[要闻]', 'abstract': '海洋工程领域旗舰会议 OCEANS 2026 于 9 月 21—24 日在美国加州蒙特雷举行，由 IEEE 海洋工程学会主办，包含约 500 篇经同行评审的技术论文、专题论坛、学生海报竞赛与超过 100 家展商的技术展示，议题覆盖水下声学、海洋观测、自主航行器、海洋能源与海洋信息技术等。会议论文后续将归档至 IEEE Xplore，是本期海洋工程与数据技术新进展的集中发布窗口。', 'source': 'IEEE OES（会议页）', 'url': 'https://tethys.pnnl.gov/events/oceans-2026-monterey', 'date': '2026-09-21'}, {'title': '11 对引物巡测中太平洋珊瑚礁全生命之树多样性', 'badge': '[论文]', 'abstract': 'Molecular Ecology Resources 刊文针对 eDNA 宏条形码“每对引物都存在偏好性扩增”这一核心难题，测试 11 对引物对中太平洋珊瑚礁五个真核生物界（色藻、真菌、后生动物、植物、原生动物）多样性的覆盖能力，并将零半径 OTU 比对公共序列库解析到尽可能细的分类阶元。全部引物合计检出五个界、35 门、62 纲的 421 个分类单元，为珊瑚礁生物多样性监测的引物组合选择提供依据。', 'source': 'Molecular Ecology Resources', 'url': 'https://doi.org/10.1111/1755-0998.70196', 'date': '2026-09-18'}, {'title': '广州海洋地质调查局 AUV 在南海超深水完成失联设备搜寻', 'badge': '[动态]', 'abstract': '广州海洋地质调查局 AUV 技术团队在南海中央海盆水深超 4000 米海域成功执行深水搜寻任务，精准定位此前失联的海底科研设备。任务基于单 AUV 平台构建“广域声学搜索—精细声学刻画—近底光学查证”的多层级递进式目标搜索模式：AUV 先以 40—60 米离底高度完成 60 余平方公里声呐全域扫测，再降至 20 米离底高度对重点目标实施高分辨率精细声学探测，最后下潜至距海底 6 米利用高性能光学设备完成近底影像查证，成功搜获海底失联设备。该任务验证了深海无人智能装备在超深水复杂环境下的作业能力，为深海资源勘探与水下应急搜救积累了经验。', 'source': '中国科学报 / 科学网', 'url': 'https://news.sciencenet.cn/htmlnews/2026/9/571169.shtm', 'date': '2026-09-09'}, {'title': '双稳态金属壳驱动的新型水下滑翔机：0.82 秒完成浮力状态切换', 'badge': '[论文]', 'abstract': 'Ocean Engineering 刊文指出，水下滑翔机以长航时见长，但传统压载系统响应慢、能耗高，限制了其在浅水河口等需要快速深度调整的复杂底质环境中的应用。研究提出以双稳态金属壳驱动的新型滑翔机，压载状态切换仅需 0.82 秒，整机体积变化等效于 ±221 克，并完成性能评估。', 'source': 'Ocean Engineering', 'url': 'https://doi.org/10.1016/j.oceaneng.2026.128114', 'date': '2026-09-17'}]}, {'title': '八、海洋数据中心', 'en': 'Ocean Data Centers', 'items': [{'title': '环北极沉积物物源数据库 CASPROD 发布', 'badge': '[数据]', 'abstract': 'Earth System Science Data 刊文发布环北极沉积物物源数据库 CASPROD，汇集环北冰洋表层沉积物的矿物学与地球化学多指标数据。北极放大效应正在加速海冰退缩、冻土消融与河流输沙增强，改变北冰洋“源到汇”沉积动力过程；该数据库以统一的多指标框架整合欧亚与北美不同源区的信号，破解此前数据碎片化、异构化导致的物源解译困难，是可直接复用的区域级数据资产。', 'source': 'Earth System Science Data', 'url': 'https://doi.org/10.5194/essd-18-6649-2026', 'date': '2026-09-10'}, {'title': 'BAMS：全球海洋预报中心十余年业务预报近实时评估', 'badge': '[论文]', 'abstract': 'Bulletin of the American Meteorological Society 刊文总结了 2012 年起在 OceanPredict 比对与验证工作组框架下建立的业务化海洋分析与预报近实时比对机制：通过让各中心预报与共同观测数据集对比，既揭示多系统间的离散度与预报不确定性，也反过来暴露数值预报与观测数据集各自的质量问题。十余年运行经验为业务化海洋数据服务的一致性与质量保障提供了制度化范例。', 'source': 'Bulletin of the American Meteorological Society', 'url': 'https://doi.org/10.1175/bams-d-25-0185.1', 'date': '2026-09-21'}, {'title': '水下数据中心是否会对 AI 条约核查构成风险', 'badge': '[论文]', 'abstract': 'arXiv 2609.18824 讨论限制前沿AI发展的国际协议核查难题：核心挑战之一是发现用于规避限制的未申报算力设施。水下数据中心被视为潜在规避路径，但其在前沿规模下的可行性与可探测性此前缺乏严肃评估。作者梳理现有水下数据中心部署，比较其相对陆基设施的建造与维护复杂度，并分析在水下开展等效 10 万张 H100 规模训练运行的可行性，指出电力供给等环节构成关键约束（海底设施与数据主权交叉议题，边缘方向供参考）。', 'source': 'arXiv (cs.CY)', 'url': 'https://arxiv.org/abs/2609.18824', 'date': '2026-09-16'}, {'title': 'GEBCO_2026 全球水深网格（15 弧秒）持续开放获取', 'badge': '[数据]', 'abstract': 'GEBCO_2026 网格于 2026 年 4 月发布，提供全球陆海高程数据，空间分辨率 15 弧秒，网格规模 43200 行 × 86400 列（约 37.3 亿个数据点）。其“基座”为 SRTM15+ 2.8 版（融合陆地地形与基于卫星重力预测的海底地形，并采用 SWOT 卫星高精度重力场与机器学习方法），再叠加 Seabed 2030 四个区域中心的多波束等实测网格，通过“移除—恢复”混合与羽化处理拼接为无缝全球地形模型。该网格已提供 Web 地图服务（WMS）图层，公众可免费使用；本期第三方数据平台也已收录该网格。', 'source': 'GEBCO / Data Basin', 'url': 'https://databasin.org/datasets/f128529f1106485c906883ecb82be7d7', 'date': '2026-09-14'}, {'title': 'Argo 全球数据汇编中心发布最新全球数据快照', 'badge': '[数据]', 'abstract': '国际 Argo 计划的全球数据汇编中心（Argo GDAC，布列斯特与蒙特雷）发布最新全球数据快照（含 BGC-Argo Sprof 子集）。Argo 是由约 3000 台自由漂流剖面浮标组成的全球阵列，测量上层 2000 米温度与盐度，每年提供约 10 万条温盐剖面及流速数据，平均间距约 3°；部分浮标还携带溶解氧、叶绿素等生化参数传感器。所有数据经自动质量控制后在数小时内近实时公开，科学质量控制（延迟模式）数据在采集后 6 个月内通过 GDAC 发布，是海洋与气候研究的关键开放数据底座。', 'source': 'SEANOE / Argo GDAC', 'url': 'https://www.seanoe.org/data/00311/42182/', 'date': '2026-09-08'}]}, {'title': '九、工具与代码资源', 'en': 'Tools & Code Resources', 'items': [{'title': 'PlanktonFlow：面向生物学家的浮游生物图像深度学习分类流水线（PCI 推荐）', 'badge': '[开源]', 'abstract': 'Peer Community in Ecology 于 9 月正式推荐开源工具 PlanktonFlow——一套面向缺乏专业计算技能的生物学家的 Python 流水线，集成图像预处理、稀有类别数据增强、多种卷积网络（ResNet、DenseNet、EfficientNet、YOLO）的训练与超参数优化、模型评估及对新数据集的预测。在 76 个类别、90723 张 FlowCAM 淡水浮游生物图像上评估，EfficientNet-B5 取得最高宏平均 F1，优于常用工具 EcoTaxa；代码与完整实操指南已在 GitHub 开源。', 'source': 'Peer Community in Ecology / GitHub', 'url': 'https://doi.org/10.24072/pci.ecology.100852', 'date': '2026-09-22'}, {'title': 'Det-LIME：面向自动海洋哺乳动物检测的可解释性工具', 'badge': '[论文]', 'abstract': 'Marine Mammal Science 刊文指出，黑箱目标检测器在海洋哺乳动物研究与监测中快速普及，但可解释性技术很少真正进入保护工作流；面向分类任务的可解释性工具又不适用于检测任务——它们忽略同一场景中的多个检测框，只输出单实例证据，且可视化分辨率低、生物学意义弱。Det-LIME 提出检测器感知的多实例局部可解释方法，为检测结果提供更贴合个体与群体的归因证据。', 'source': 'Marine Mammal Science', 'url': 'https://doi.org/10.1111/mms.70276', 'date': '2026-09-20'}, {'title': '无人机 LiDAR 快速反演北极海冰厚度（FACE2024 航次）', 'badge': '[工具]', 'abstract': 'Remote Sensing Letters 刊文提出一套快速、高分辨率的无人机 LiDAR 海冰厚度（SIT）反演工作流，数据来自“中山大学极地”号 R/V Zhong Shan Da Xue Ji Di 在 FACE2024（Following Arctic/Antarctic iCE 2024）航次采集的点云。流程整合点云预处理、局地海面高程估计、点云分类、雪面干舷计算与静力平衡换算，针对极区航行与作业安全对时效性、空间分辨率与可达性的需求，把单次航测直接转为厚度产品。', 'source': 'Remote Sensing Letters', 'url': 'https://doi.org/10.1080/2150704x.2026.2731606', 'date': '2026-09-16'}, {'title': '海洋脊椎动物 eDNA 宏条形码方法评估与开源流程 MVeM', 'badge': '[工具]', 'abstract': 'Metabarcoding and Metagenomics 刊文指出，eDNA 已成为海洋脊椎动物多样性研究的重要工具，但工作流各环节的方法差异会影响结果，亟需标准化且易用的方案。研究评估了两种 eDNA 提取策略与两种校正能力不同的 DNA 聚合酶的表现，并介绍了开源的海洋脊椎动物 eDNA 宏条形码生物信息流程（MVeM），为用户提供从建库到分析的规范化路径。', 'source': 'Metabarcoding and Metagenomics', 'url': 'https://doi.org/10.3897/mbmg.10.191426', 'date': '2026-09-10'}, {'title': 'Copernicus Marine Toolbox 发布 2.5.0b1', 'badge': '[工具]', 'abstract': 'Copernicus Marine Toolbox（官方 Python 库与 CLI 数据访问工具）发布 2.5.0b1 预发布版。工具箱提供 describe（浏览产品目录与元数据）、subset（按变量、经纬度范围、时间与深度切片，支持 NetCDF/Zarr/CSV/Parquet）、get（按通配符或正则下载原始文件）、open_dataset（经 xarray 远程惰性加载）与 read_dataframe（直接读入 pandas）等能力，数据量与带宽均无配额限制；支持 pip、conda-forge、Docker 与独立可执行文件多种安装方式，可覆盖约 97% 的 Copernicus Marine 数据集切片需求。', 'source': 'PyPI / GitHub (mercator-ocean/copernicus-marine-toolbox)', 'url': 'https://github.com/mercator-ocean/copernicus-marine-toolbox/releases', 'date': '2026-09-15'}]}]


def main():
    src_path = 'feishu_write_doc.py'
    with open(src_path, 'r', encoding='utf-8') as f:
        content = f.read()

    new_repr = repr(SECTIONS).replace('\\x27', "'")
    pattern = re.compile(r'SECTIONS = \[.*?(?=\ndef tr\(|\n# ---|\Z)', re.DOTALL)
    if not pattern.search(content):
        raise SystemExit('ERROR: SECTIONS block not found in feishu_write_doc.py')
    content = pattern.sub('SECTIONS = ' + new_repr + '\n\n\n', content, count=1)

    with open(src_path, 'w', encoding='utf-8') as f:
        f.write(content)

    total = sum(len(s['items']) for s in SECTIONS)
    effective = sum(1 for s in SECTIONS for i in s['items'] if i.get('badge') != '[备注]')
    print(f'OK: SECTIONS written. Total items: {total} (effective: {effective})')


if __name__ == '__main__':
    main()
